SELECT id, category, cost, COUNT(stock_qty) OVER (PARTITION BY supplier_id, category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_stock_qty, SUM(stock_qty) OVER (PARTITION BY supplier_id, category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_stock_qty, MAX(stock_qty) OVER (PARTITION BY supplier_id, category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_stock_qty, LAST_VALUE(cost) IGNORE NULLS OVER (PARTITION BY DATE_TRUNC('week', launch_date), brand ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cost FROM products
